contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] calldata _tos, uint v) public {
        require(_tos.length > 0);
        bool returnedSuccess;
        bool reverted;
        try c.transfer(from, caddress, _tos, v) returns (bool ok) {
            returnedSuccess = ok;
            reverted = false;
        } catch {
            returnedSuccess = false;
            reverted = true;
        }
        // General rule: transfer either completes successfully and returns true,
        // or it reverts. In other words, it never returns false without reverting.
        assert(reverted || returnedSuccess);
    }
}

